/**
 * Splits an ordered dataset into a training set and a test set by index.
 */
public class DataSplitter {

    private final double[][] rows;
    private final String[] labels;
    private final int trainCount;

    public DataSplitter(double[][] rows, String[] labels, int trainCount) {
        if (rows == null || labels == null || rows.length != labels.length) {
            throw new IllegalArgumentException("rows and labels must be the same length");
        }
        if (trainCount < 0 || trainCount > rows.length) {
            throw new IllegalArgumentException("trainCount out of range: " + trainCount);
        }
        this.rows = rows;
        this.labels = labels;
        this.trainCount = trainCount;
    }

    public int trainSize() {
        return trainCount;
    }

    public int testSize() {
        return rows.length - trainCount;
    }

    public double[] trainRow(int i) {
        return rows[i];
    }

    public String trainLabel(int i) {
        return labels[i];
    }

    public double[] testRow(int i) {
        return rows[trainCount + i];
    }

    public String testLabel(int i) {
        return labels[trainCount + i];
    }
}
